(()=>{const {t,esc,request,status,duration}=F;let data=null,accessToken=new URLSearchParams(location.hash.slice(1)).get('token')||'',printURL=null;const token=()=>accessToken,options=method=>({method,headers:{'X-Participant-Token':token()}});document.querySelector('#lookupForm').addEventListener('submit',e=>{e.preventDefault();try{const u=new URL(e.target.elements.link.value,location.href),value=new URLSearchParams(u.hash.slice(1)).get('token');if(!/^[a-f0-9]{64}$/.test(value))throw Error();accessToken=value;location.hash='token='+value;load()}catch{status('رابط المشارك غير صالح.',true)}});async function load(){if(!token()){document.querySelector('#participantLookup').hidden=false;return}document.querySelector('#participantLookup').hidden=true;try{data=await request('/api/participant',options('GET'));render()}catch(e){status(e.message,true)}}function render(){if(!data)return;const p=data.participant,e=I18N.event(data.event),confirmed=p.state==='confirmed',card=document.querySelector('#participantContent');card.hidden=false;card.innerHTML=`<div class="participant-layout"><div class="participant-badge"><span>RUN MSAFAT</span><h2>${esc(p.name)}</h2><p>${esc(e.name)}</p><strong class="bib-number">#${p.bib}</strong><p>${esc(I18N.distance(p.distance))}</p><span class="state-pill">${t(p.state)}</span>${confirmed?`<img class="qr" src="${data.qr}" alt="${t('بطاقة QR للمشارك')}"><p>${t(p.checkedIn?'تم تأكيد الحضور':'اعرض البطاقة عند الاستقبال')}</p>`:''}<button class="outline-btn" id="printCard" ${!confirmed?'disabled':''}>${t('طباعة بطاقة المشاركة')}</button><button class="outline-btn" id="printCertificate" ${!data.certificateEligible?'disabled':''}>${t('تنزيل شهادة المشاركة')}</button></div><section class="feature-card"><h2>${t('بيانات المشاركة')}</h2><p>${e.timePending?new Date(e.start).toLocaleDateString(I18N.lang):new Date(e.start).toLocaleString(I18N.lang)}</p>${p.state==='waitlisted'?`<p class="notice">${t('أنت بقائمة الانتظار. افتح هذه الصفحة لمتابعة توفر مكان.')}</p>`:''}${p.state==='pending_payment'?`<div class="payment-box"><p>${t('رسوم المشاركة')}: ${new Intl.NumberFormat(I18N.lang,{style:'currency',currency:'ILS'}).format(p.feeMinor/100)}</p><button class="btn" id="payButton" ${!data.paymentsReady?'disabled':''}>${t('الدفع عبر PayPal')}</button><button class="outline-btn" id="capturePayment">${t('التحقق من الدفع')}</button>${!data.paymentsReady?`<p>${t('الدفع غير مفعّل لدى المنظّم.')}</p>`:''}</div>`:''}<form id="participantForm"><div class="form-grid"><label>${t('الاسم الكامل')}<input name="name" required minlength="2" maxlength="100" value="${esc(p.name)}"></label><label>${t('البريد الإلكتروني')}<input name="email" type="email" required maxlength="254" value="${esc(p.email)}" dir="ltr"></label><label>${t('رقم واتساب مع رمز الدولة')}<input name="phone" required pattern="\\+[1-9][0-9]{7,14}" value="${esc(p.phone)}" dir="ltr"></label><label>${t('المسافة')}<select name="distance">${e.distances.map(d=>`<option ${d===p.distance?'selected':''}>${esc(d)}</option>`).join('')}</select></label><label>${t('العمر (اختياري)')}<input name="age" type="number" min="0" max="100" value="${p.age??''}"></label></div><button class="btn" ${p.state==='cancelled'||e.registrationProfile==='student'?'disabled':''}>${t('حفظ التعديلات')}</button></form>${data.result?`<p>${t('نتيجتك')}: <b dir="ltr">${duration(data.result.seconds)}</b></p>`:''}<p class="muted">${t('الشهادة تصبح متاحة بعد السباق ونشر نتيجتك.')}</p>${e.registrationProfile==='student'?`<p>${t('لتعديل بيانات الطالب تواصل مع المنظّم.')}</p>`:''}<hr><p>${t('إلغاء المشاركة يوقف التذكيرات. رسوم الدفع لا تُعاد تلقائيًا؛ تواصل مع المنظّم بشأن الاسترداد.')}</p><button class="outline-btn" id="cancelParticipant" ${p.state==='cancelled'?'disabled':''}>${t('إلغاء المشاركة')}</button><a class="outline-btn" href="race.html?event=${encodeURIComponent(e.id)}">${t('تفاصيل الماراثون')}</a></section></div>`;document.querySelector('#participantForm').onsubmit=async ev=>{ev.preventDefault();try{const d=await request('/api/participant',{...options('PUT'),body:JSON.stringify(Object.fromEntries(new FormData(ev.target)))});status(d.message);await load()}catch(e){status(e.message,true)}};document.querySelector('#cancelParticipant').onclick=async()=>{if(!confirm(t('هل تؤكد إلغاء المشاركة؟')))return;try{const d=await request('/api/participant/cancel',options('POST'));status(d.message);await load()}catch(e){status(e.message,true)}};document.querySelector('#printCard').onclick=()=>{document.body.classList.remove('print-certificate');document.body.classList.add('print-badge');printSafely()};document.querySelector('#printCertificate').onclick=async()=>{if(!data.certificateEligible)return;document.querySelector('#certificate').innerHTML=`<div class="certificate-inner"><p class="certificate-brand">RUN MSAFAT</p><p>${t('شهادة مشاركة')}</p><h1>${esc(p.name)}</h1><p>${t('شارك في')}</p><h2>${esc(e.name)}</h2><p>${esc(I18N.distance(p.distance))} · ${new Date(e.start).toLocaleDateString(I18N.lang)}</p><p>${t('الوقت')}: <b dir="ltr">${duration(data.result.seconds)}</b> · #${p.bib}</p><div class="certificate-line"></div><p>${t('كل مسافة حكاية تستحق أن تُروى.')}</p></div>`;const certificate=document.querySelector('#certificate'),button=document.querySelector('#printCertificate');button.disabled=true;certificate.hidden=false;certificate.classList.add('certificate-export');try{await document.fonts.ready;const canvas=await html2canvas(certificate,{scale:2,backgroundColor:'#ffffff',logging:false});const pdf=new window.jspdf.jsPDF({orientation:'landscape',unit:'mm',format:'a4'});pdf.addImage(canvas.toDataURL('image/png'),'PNG',0,0,297,210);pdf.save('Run_Msafat_certificate_'+p.bib+'.pdf')}catch{status(t('تعذّر إنشاء الشهادة. حاول مرة أخرى.'),true)}finally{certificate.hidden=true;certificate.classList.remove('certificate-export');button.disabled=false}};const pay=document.querySelector('#payButton');if(pay)pay.onclick=async()=>{pay.disabled=true;try{const d=await request('/api/participant/payment',options('POST'));if(d.url)location.href=d.url}catch(e){status(e.message,true);pay.disabled=false}};const capture=document.querySelector('#capturePayment');if(capture)capture.onclick=capturePayment;}async function capturePayment(){const button=document.querySelector('#capturePayment');if(button)button.disabled=true;try{const d=await request('/api/participant/payment/capture',options('POST'));status(d.message);history.replaceState(null,'',location.pathname+location.hash);await load()}catch(e){status(e.message,true);if(button)button.disabled=false}}function printSafely(){printURL=location.href;history.replaceState(null,'',location.pathname);window.print()}window.addEventListener('afterprint',()=>{if(printURL){history.replaceState(null,'',printURL);printURL=null}});load().then(()=>{if(new URLSearchParams(location.search).get('payment')==='return'&&data?.participant.state==='pending_payment')capturePayment()});window.addEventListener('languagechange',render)})();
